// Verify newest backup in watch dir
const fs = require('fs');
const p = '$param:watch_path';
const maxAgeH = Number('$param:max_age_hours') || 24;
let status = 'FAIL', detail = '';
try {
  const files = fs.readdirSync(p).filter(f => !f.startsWith('.')).map(f => {
    const st = fs.statSync(require('path').join(p, f));
    return { f, mtime: st.mtimeMs, size: st.size };
  }).sort((a, b) => b.mtime - a.mtime);
  if (!files.length) detail = 'directory empty';
  else {
    const newest = files[0];
    const ageH = (Date.now() - newest.mtime) / 3600000;
    status = ageH <= maxAgeH ? 'PASS' : 'FAIL';
    detail = `${newest.f} · ${(newest.size/1024).toFixed(1)}KB · age ${ageH.toFixed(1)}h (max ${maxAgeH}h)`;
  }
} catch (e) { detail = 'error: ' + e.message; }
const icon = status === 'PASS' ? '✅' : '🔴';
return [{ json: { content: `${icon} **Backup check ${status}** — \`${p}\`\n${detail}` } }];
